body.raw:
{
  "userId": "00000000-0000-4000-8000-000000000000",
  "subject": "Mantenimiento programado",
  "message": "El sábado de 2 a 4 a. m. la app no estará disponible."
}

graphql.query:
mutation ($email: String!) {
  requestPasswordReset(email: $email) { ok message }
}

mutation ($email: String!, $code: String!, $newPassword: String!) {
  resetPassword(email: $email, code: $code, newPassword: $newPassword) { ok message }
}

mutation ($refreshToken: String!) {
  refreshToken(refreshToken: $refreshToken) { token refreshToken expiresIn user { email } }
}

mutation ($refreshToken: String) {
  logout(refreshToken: $refreshToken) { ok message }
}

mutation ($token: String!) {
  verifyEmail(token: $token) { email emailVerified }
}

mutation {
  sendVerificationEmail { ok message }
}

mutation ($ids: [Int!]!) {
  reorderAccounts(ids: $ids) { id name sortOrder }
}

query ($accountId: Int!, $month: String) {
  creditCardStatement(accountId: $accountId, month: $month) {
    month periodStart periodEnd dueDate balance minimumPayment availableCredit utilization
  }
}

mutation {
  createDefaultCategories { id name color }
}

mutation ($sourceId: Int!, $targetId: Int!) {
  mergeCategories(sourceId: $sourceId, targetId: $targetId) { movedExpenses movedFixedExpenses target { id name } }
}

mutation ($categoryId: Int!, $monthlyLimit: Float) {
  setCategoryLimit(categoryId: $categoryId, monthlyLimit: $monthlyLimit) { name monthlyLimit spentThisMonth }
}

mutation ($sourceId: Int!, $targetId: Int!) {
  mergeContacts(sourceId: $sourceId, targetId: $targetId) { movedNetWorthEntries movedExpenseSplits target { name } }
}

query ($prefix: String!) {
  expenseSuggestions(prefix: $prefix, limit: 5) { description timesUsed averageAmount accountId categoryId }
}

mutation ($csv: String) {
  importExpensesCsv(csv: $csv) { imported totalAmount errors { line message } }
}

query ($from: String!, $to: String!) {
  exportExpensesCsv(from: $from, to: $to) { filename rows content }
}

mutation ($expenseId: Int!, $parts: [SplitPartInput!]!) {
  splitExpense(expenseId: $expenseId, parts: $parts) {
    yourShare
    splits { contactName amount netWorthEntryId }
  }
}

mutation ($month: String) {
  checkBudgetAlerts(month: $month) { type label spent limit percentUsed threshold notified }
}

mutation ($fixedExpenseId: Int!, $month: String!, $accountId: Int!) {
  fixedExpenseToExpense(fixedExpenseId: $fixedExpenseId, month: $month, accountId: $accountId) {
    expense { id amount date description }
    payment { month expenseId }
  }
}

mutation {
  sendPaymentReminders(daysAhead: 5) { name amount dayOfMonth notified }
}

mutation ($ids: [Int!]!) {
  reorderNetWorth(ids: $ids) { id label kind sortOrder }
}

mutation ($entryId: Int!) {
  syncNetWorthWithAccount(entryId: $entryId) { previousAmount month entry { label amount } }
}

mutation {
  createProjection(name: "Ahorro 5 años", monthlyContribution: 2000, annualRate: 10, months: 60) {
    id startingAmount finalAmount totalContributed interestEarned
    schedule(step: 12) { month balance }
  }
}

query {
  projections { id name months finalAmount interestEarned }
}

mutation ($id: Int!) {
  deleteProjection(id: $id) { ok message }
}

query ($month: String) {
  dailySpending(month: $month) { month total dailyBudget days { date total cumulative } }
}

query {
  categoryComparison {
    monthA monthB totalA totalB
    categories { categoryName totalA totalB difference percentChange }
  }
}

mutation {
  registerDevice(token: "fcm-token-de-ejemplo-123456", platform: "android") { id platform lastSeenAt }
}

query {
  devices { id platform lastSeenAt }
}

mutation {
  sendDailySummary { date sent skipped }
}

mutation {
  createApiToken(name: "Atajos iPhone") { token apiToken { id name } }
}

mutation {
  createCardNameMapping(cardName: "BBVA **1234", accountId: 1) { id cardName account { name } }
}

mutation {
  webhookExpense(amount: 59.90, card: "BBVA **1234", description: "Oxxo", category: "Comida") { id amount accountName categoryName date }
}
